using System.Collections.Generic;

// Declarar un diccionario: clave string, valor int
Dictionary<string, int> inventario = new Dictionary<string, int>();

// Agregar pares clave-valor
inventario.Add("Pociones", 5);
inventario.Add("Flechas", 30);
inventario.Add("Monedas", 150);

// Acceder por clave
Debug.Log(inventario["Pociones"]); // 5

// Modificar un valor existente
inventario["Pociones"] = 4;

// Verificar si una clave existe (SIEMPRE hacerlo antes de acceder)
if (inventario.ContainsKey("Espada"))
{
    Debug.Log(inventario["Espada"]);
}

// TryGetValue: forma segura de obtener un valor
int cantidad;
if (inventario.TryGetValue("Flechas", out cantidad))
{
    Debug.Log("Flechas: " + cantidad);
}

// Eliminar una entrada
inventario.Remove("Monedas");

// Cantidad de pares en el diccionario
Debug.Log(inventario.Count); // 2

